// src/api/config.js
export const FRONT_BASE =
  (process.env.PUBLIC_URL || "/woodenpages").replace(/\/+$/, ""); // "/woodenpages"

export const BASE_URL = process.env.REACT_APP_API_BASE || ""; // 운영시만 의미 있음
export const IS_DEMO =
  (process.env.REACT_APP_IS_DEMO ?? "true").toLowerCase() === "true";

export const apiPath = (p) => {
  const clean = p.startsWith("/") ? p : `/${p}`;
  return IS_DEMO ? `${FRONT_BASE}${clean}` : `${BASE_URL}${clean}`;
};
